<script setup>
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { display, label, userOptions, investigatorOptions } from './common.js'
const route=useRoute(),store=useDemo()
const event=computed(()=>store.getEvent(route.params.id))
const tab=ref(route.query.tab || 'overview'),error=ref(''),remarks=ref(''),correction=ref(false)
const reports=computed(()=>store.visibleRecords('reports').filter(r=>r.eventId===event.value?.id))
const cases=computed(()=>store.visibleRecords('cases').filter(r=>r.eventId===event.value?.id))
const actions=computed(()=>store.visibleRecords('actions').filter(r=>r.eventId===event.value?.id))
const evidence=computed(()=>store.visibleRecords('evidence').filter(r=>r.eventId===event.value?.id || event.value?.evidenceIds?.includes(r.id)))
function transition(status){try{error.value='';store.transition(event.value.id,status,remarks.value);correction.value=false;remarks.value=''}catch(e){error.value=e.message}}
function assign(value){try{store.saveEvent({...event.value,investigatorId:value});error.value=''}catch(e){error.value=e.message}}
const kv=(obj)=>Object.entries(obj || {}).filter(([k])=>!['id','ownerId','officeId'].includes(k))
</script>
<template><div class="page-wrap">
 <template v-if="event"><PageHeader :title="event.ref" :subtitle="`${event.type} · ${event.place || 'Location unknown'}`" eyebrow="Incident workspace"><template #actions><q-btn flat no-caps label="Register" to="/admin/incidents"/><q-btn v-if="store.can('review',event)" outline no-caps icon="edit" label="Edit particulars" :to="`/admin/incidents/${event.id}/edit`"/><q-btn v-if="store.can('investigate',event)" color="primary" no-caps icon="fact_check" label="Investigation" :to="`/admin/investigations/${event.id}`"/></template></PageHeader>
 <q-banner v-if="error" rounded class="bg-red-1 text-negative q-mb-md">{{error}}</q-banner>
 <div class="panel toolbar-row q-mb-md"><StatusBadge :status="event.status"/><q-chip square>{{label(event.seriousness)}}</q-chip><span class="muted">{{event.dateUnknown?'Unknown date':display(event.date)}} · {{event.timeUnknown?'Unknown time':display(event.time)}}</span><q-space/><template v-if="store.can('review',event)"><q-btn v-if="['submitted','resubmitted'].includes(event.status)" color="primary" no-caps label="Start review" @click="transition('under_review')"/><q-btn v-if="event.status==='under_review'" outline no-caps label="Request corrections" @click="correction=true"/><q-btn v-if="event.status==='under_review'" color="positive" no-caps label="Validate report" @click="transition('validated')"/></template></div>
 <div class="panel"><q-tabs v-model="tab" align="left" active-color="primary" inline-label outside-arrows mobile-arrows><q-tab name="overview" label="Overview" no-caps/><q-tab name="vessels" label="Vessels" no-caps/><q-tab name="consequences" label="Consequences" no-caps/><q-tab name="evidence" label="Evidence" no-caps/><q-tab name="chronology" label="Chronology" no-caps/><q-tab name="reports" label="MAIC reports" no-caps/><q-tab name="enforcement" label="Enforcement" no-caps/><q-tab name="actions" label="Follow-up" no-caps/><q-tab name="lineage" label="Source lineage" no-caps/></q-tabs><q-separator/>
 <q-tab-panels v-model="tab" animated>
  <q-tab-panel name="overview"><div class="form-grid"><section><div class="section-title">Occurrence and account</div><dl class="ops-kv"><template v-for="[k,v] in [['Incident type',event.type],['Secondary types',event.secondaryTypes?.join(', ')],['Impact types',event.impactTypes?.join(', ')],['Position quality',event.positionQuality],['Latitude',event.lat],['Longitude',event.lon],['Reporting account',store.state.users.find(u=>u.id===event.ownerId)?.name],['Reporting office',event.officeId]]" :key="k"><dt>{{k}}</dt><dd>{{display(v)}}</dd></template></dl></section><section><div class="section-title">Office relationships</div><dl class="ops-kv"><template v-for="[k,v] in [['Area of responsibility',event.aor],['Homeport office',event.homeport],['CPC office',event.cpc],['Actual issuing office',event.issuingOffice]]" :key="k"><dt>{{k}}</dt><dd>{{display(v)}}</dd></template></dl><q-select v-if="store.can('investigate',event)" :model-value="event.investigatorId" @update:model-value="assign" :options="investigatorOptions(store)" emit-value map-options outlined clearable label="Assigned investigator"/></section><section class="span-2" v-for="[k,v] in [['Event narrative',event.summary],['Initial response',event.initialActions],['Recommendations',event.recommendations]]" :key="k"><div class="section-title">{{k}}</div><p class="ops-narrative">{{display(v)}}</p></section></div></q-tab-panel>
  <q-tab-panel name="vessels"><q-expansion-item v-for="(v,i) in event.vessels" :key="v.id || i" :label="`${v.name || 'Unnamed vessel'} · ${v.role || 'Involved vessel'}`" icon="directions_boat" default-opened class="q-mb-md"><dl class="ops-kv q-pa-md"><template v-for="[k,value] in kv(v)" :key="k"><dt>{{label(k.replace(/([A-Z])/g,' $1'))}}</dt><dd>{{typeof value==='object' ? Object.entries(value || {}).map(([a,b])=>`${a}: ${display(b)}`).join(' · ') : display(value)}}</dd></template></dl></q-expansion-item><p v-if="!event.vessels?.length" class="muted">Vessel particulars have not been supplied.</p></q-tab-panel>
  <q-tab-panel name="consequences"><p class="muted">Values describe this event. Unknown counts remain unknown across cumulative report revisions.</p><dl class="ops-kv"><template v-for="[k,v] in kv(event.consequences)" :key="k"><dt>{{label(k.replace(/([A-Z])/g,' $1'))}}</dt><dd>{{display(v)}}</dd></template></dl></q-tab-panel>
  <q-tab-panel name="evidence"><div class="toolbar-row"><div class="section-title">Linked source material</div><q-space/><q-btn flat no-caps color="primary" label="Manage evidence" :to="{path:'/admin/documents',query:{eventId:event.id}}"/></div><q-list separator><q-item v-for="e in evidence" :key="e.id"><q-item-section avatar><q-icon name="description"/></q-item-section><q-item-section><q-item-label>{{e.name}}</q-item-label><q-item-label caption>{{e.type}} · {{e.sourceRef || 'No source reference'}} · {{e.notes}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="e.status"/></q-item-section></q-item></q-list><p v-if="!evidence.length" class="muted">No evidence metadata linked.</p></q-tab-panel>
  <q-tab-panel name="chronology"><div class="timeline"><section v-for="(h,i) in [...(event.history || [])].reverse()" :key="h.id || i" class="q-mb-lg"><StatusBadge :status="h.status"/><p class="q-mb-xs">{{h.actorName || store.state.users.find(u=>u.id===h.actorId)?.name || 'Recorded actor'}} · {{h.at ? new Date(h.at).toLocaleString() : 'Time unknown'}}</p><p class="muted ops-narrative">{{h.remarks || 'Status recorded'}}</p></section></div></q-tab-panel>
  <q-tab-panel name="reports"><q-list separator><q-item v-for="r in reports" :key="r.id"><q-item-section><q-item-label>MAIC {{r.type}} · revision {{r.revision}}</q-item-label><q-item-label caption>{{r.date}} · {{r.preparedBy || 'Preparer pending'}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="r.status"/></q-item-section></q-item></q-list><p v-if="!reports.length" class="muted">No MAIC revision recorded yet.</p><q-btn v-if="store.can('investigate',event)" class="q-mt-md" color="primary" no-caps label="Open investigation workbench" :to="`/admin/investigations/${event.id}`"/></q-tab-panel>
  <q-tab-panel name="enforcement"><template v-if="store.can('enforce',event)"><q-list separator><q-item v-for="c in cases" :key="c.id" clickable :to="`/admin/cases/${c.id}`"><q-item-section>{{c.caseNumber}} · {{c.party}}</q-item-section><q-item-section side><StatusBadge :status="c.status"/></q-item-section></q-item></q-list><q-btn class="q-mt-md" color="primary" no-caps label="Create linked case" :to="{path:'/admin/cases',query:{eventId:event.id,new:'1'}}"/></template><p v-else class="muted">Enforcement details require enforcement permission.</p></q-tab-panel>
  <q-tab-panel name="actions"><q-list separator><q-item v-for="a in actions" :key="a.id"><q-item-section>{{a.title}}<q-item-label caption>Due {{a.dueDate || 'not assigned'}} · {{store.state.users.find(u=>u.id===a.ownerId)?.name || 'Unassigned'}}</q-item-label></q-item-section><q-item-section side><StatusBadge :status="a.status"/></q-item-section></q-item></q-list><q-btn class="q-mt-md" outline no-caps label="Manage follow-up" :to="{path:'/admin/actions',query:{eventId:event.id}}"/></q-tab-panel>
  <q-tab-panel name="lineage"><dl class="ops-kv"><template v-for="[k,v] in [['Source type',event.sourceType],['Source reference',event.sourceRef],['Received date',event.receivedDate],...kv(event.sourceLineage)]" :key="k"><dt>{{label(k)}}</dt><dd>{{display(v)}}</dd></template></dl><p class="muted">Source lineage records the synthetic import file, sheet, row and merge group without merging distinct event consequences.</p></q-tab-panel>
 </q-tab-panels></div>
 <q-dialog v-model="correction"><q-card style="width:550px;max-width:94vw"><q-card-section><div class="text-h6">Correction request</div><q-input class="q-mt-md" v-model="remarks" outlined type="textarea" label="Required correction instructions"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="primary" no-caps label="Send request" :disable="!remarks.trim()" @click="transition('correction_requested')"/></q-card-actions></q-card></q-dialog>
 </template><section v-else class="panel"><h2>Incident unavailable</h2><p>This record does not exist or is outside your permitted scope.</p><q-btn color="primary" no-caps label="Return to register" to="/admin/incidents"/></section>
</div></template>
<style scoped>.ops-kv{display:grid;grid-template-columns:minmax(140px,1fr) 2fr;gap:10px 18px;margin:12px 0}.ops-kv dt{color:var(--muted,#64748b)}.ops-kv dd{margin:0;overflow-wrap:anywhere}.ops-narrative{white-space:pre-wrap;line-height:1.7}@media(max-width:600px){.ops-kv{grid-template-columns:1fr;gap:3px}.ops-kv dd{margin-bottom:12px}}</style>
